const 行動類型表 = Object.freeze({ '角色同步':'角色同步','任务同步':'任務同步','任務同步':'任務同步','通讯':'通訊','通訊':'通訊','一般消费':'一般消費','一般消費':'一般消費','交易':'交易','物品取得':'物品取得','物品使用':'物品使用','物品丢弃':'物品丟棄','装备':'裝備','技能':'技能','技能资料':'技能資料','生活技能':'生活技能','NPC服务':'NPC服務','队伍':'隊伍','关系':'關係','状态':'狀態','狀態':'狀態','时间':'時間','移动':'移動','属性':'屬性','任务奖励':'任務獎勵','战斗':'戰鬥' });
const 正規化行動輸入 = input => {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return input;
  const raw = 複製輸入(input);
  raw.類型 = 行動類型表[raw.類型] || raw.類型;
  raw.來源 = 文字值(raw.來源, '文字互動');
  raw.建立時間 = 文字值(raw.建立時間);
  raw.內容 = raw.內容 && typeof raw.內容 === 'object' ? raw.內容 : {};
  if (raw.類型 === '角色同步') {
    const identity = 文字值(raw.內容.身份);
    const roleType = 文字值(raw.內容.角色類型 || raw.內容.類型);
    raw.內容.角色類型 = /玩家/.test(identity) || ['玩家角色','原作人物','其他玩家'].includes(roleType) ? '玩家角色' : 'NPC';
    const source = 文字值(raw.內容.資料來源 || raw.內容.资料来源);
    raw.內容.資料來源 = ['原作','原作人物','電影原創','电影原创'].includes(source) ? '原作' : '原創';
    delete raw.內容.類型;
    delete raw.內容.资料来源;
  }
  if (raw.類型 === '任務同步') {
    raw.內容.類型 = 任務類型表[raw.內容.類型] || raw.內容.類型;
    raw.內容.狀態 = 任務狀態表[raw.內容.狀態] || raw.內容.狀態;
    raw.內容.發起者ID = 文字值(raw.內容.發起者ID || raw.內容.發布者ID || raw.內容.发布者ID);
    raw.內容.參與者ID = 陣列值(raw.內容.參與者ID ?? raw.內容.參與者 ?? raw.內容.参与者).map(value => ['user','{{user}}'].includes(文字值(value)) ? 'player' : 文字值(value)).filter(Boolean);
    delete raw.內容.發布者ID; delete raw.內容.发布者ID; delete raw.內容.參與者; delete raw.內容.参与者;
  }
  if (raw.類型 === '通訊') {
    const type = 文字值(raw.內容.類型 || raw.內容.类型);
    raw.內容.類型 = /系統|系统|通知/.test(type) ? '系統通知' : '私人訊息';
    raw.內容.已讀 = raw.內容.已讀 ?? raw.內容.已读 ?? false;
  }
  if (raw.類型 === '隊伍') {
    raw.內容.新隊長ID = 文字值(raw.內容.新隊長ID);
    raw.內容.戰利品規則 = 文字值(raw.內容.戰利品規則);
  }
  if (raw.類型 === '交易') {
    raw.內容.交易對象ID = 文字值(raw.內容.交易對象ID);
    raw.內容.明細 = 陣列值(raw.內容.明細).map(line => ({
      ...line, 物品ID:文字值(line?.物品ID), 模板ID:文字值(line?.模板ID),
      物品快照:line?.物品快照 ?? null
    }));
    raw.內容.玩家支付Col = Math.abs(Number(raw.內容.玩家支付Col ?? 0) || 0);
    raw.內容.對方支付Col = Math.abs(Number(raw.內容.對方支付Col ?? 0) || 0);
  }
  if (raw.類型 === '一般消費') {
    raw.內容.玩家支付Col = Math.abs(Number(raw.內容.玩家支付Col ?? 0) || 0);
    raw.內容.玩家取得Col = Math.abs(Number(raw.內容.玩家取得Col ?? 0) || 0);
    raw.內容.取得物品 = 陣列值(raw.內容.取得物品);
    raw.內容.失去物品 = 陣列值(raw.內容.失去物品);
  }
  return raw;
};

