  for (const [id, task] of Object.entries(data.任務)) {
    if (!npcOnlyTypes.has(task.類型)) continue;
    if (data.角色?.[task.發起者ID]?.類型 !== 'NPC') {
      context.addIssue({
        code: 'custom',
        path: ['任務', id, '發起者ID'],
        message: '任務委託只能由已建檔的NPC發出'
