  }
}).transform(data => {
  data.玩家.ID = 'player';
  data.玩家.HP.當前 = _.clamp(data.玩家.HP.當前, 0, data.玩家.HP.最大);
  const selfAliases = new Set(['user', '{{user}}', String(data.玩家.名稱 || '').trim()].filter(Boolean));
  for (const memberId of Object.keys(data.玩家.隊伍.成員)) {
    if (memberId !== 'player' && selfAliases.has(String(memberId).trim())) delete data.玩家.隊伍.成員[memberId];
