  data.系統.行動請求 = data.系統.行動請求.slice(-80);
  data.系統.已處理行動ID = _.uniq(data.系統.已處理行動ID).slice(-1000);
  data.系統.行動日誌 = data.系統.行動日誌.slice(-300);
  data.系統.待確認行動 = Object.fromEntries(Object.entries(data.系統.待確認行動).slice(-80));
  for (const [id, character] of Object.entries(data.角色)) {
    character.ID = id;
    if (character.戰鬥) character.戰鬥.HP.當前 = _.clamp(character.戰鬥.HP.當前, 0, character.戰鬥.HP.最大);
  }
  return data;
});

