(async () => {
  const VERSION = '5.2.4';
  const TAG = `[SAOP V${VERSION} 核心調度器]`;
  if (globalThis.__SAOP_V5_DISPATCHER_VERSION__ === VERSION) return;
  globalThis.__SAOP_V5_DISPATCHER_VERSION__ = VERSION;
  globalThis.__SAOP_V5_DISPATCHER_LOADED__ = true;

  const clone = value => value === undefined ? undefined : JSON.parse(JSON.stringify(value));
  const finite = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
  const integer = (value, fallback = 0) => Math.trunc(finite(value, fallback));
  const clamp = (value, min, max) => Math.max(min, Math.min(max, finite(value)));
  const nowText = state => `${state?.世界?.日期 || '2022-11-06'} ${state?.世界?.時間 || '13:25'}`;
  const stableStringify = value => {
    if (value === null || typeof value !== 'object') return JSON.stringify(value);
    if (Array.isArray(value)) return `[${value.map(stableStringify).join(',')}]`;
    return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${stableStringify(value[key])}`).join(',')}}`;
  };
  const hashText = value => {
    let hash = 2166136261;
    for (const char of String(value ?? '')) {
      hash ^= char.charCodeAt(0);
      hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(36);
  };
  const uniqueId = prefix => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  const normalizeText = value => String(value ?? '')
    .normalize('NFKC')
    .replace(/[\u00a0\u3000]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const canonicalCharacterId = value => {
    const raw = normalizeText(value);
    if (!raw || raw === 'player') return raw || 'player';
    if (/^character-[a-z0-9][a-z0-9-]*$/i.test(raw)) return raw.toLowerCase();
    const slug = raw.toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '') || hashText(raw);
    return `character-${slug}`;
  };
  const stateFromPayload = payload => {
    if (payload?.stat_data && typeof payload.stat_data === 'object') return payload.stat_data;
    return payload && typeof payload === 'object' ? payload : null;
  };
  const STARTER_ITEM_NAMES = Object.freeze({
    'starter-weapon-sword':'初始单手剑','starter-weapon-rapier':'初始细剑','starter-weapon-scimitar':'初始弯刀',
    'starter-weapon-dagger':'初始短剑','starter-weapon-mace':'初始战锤','starter-weapon-axe':'初始战斧',
    'starter-weapon-spear':'初始长枪','starter-weapon-greatsword':'初始双手剑','starter-weapon-katana2h':'初始双手太刀',
    'consumable-healing-potion-small':'初级回复药水','food-black-bread':'黑面包','tool-portable-whetstone':'便携磨刀石'
  });
  const usefulItemName = value => {
    const text = normalizeText(value);
    return text && !/^(?:未知物品|未命名物品|unknown item)$/i.test(text) ? text : '';
  };
  const inferredItemName = item => {
    const original = item?._原始 && typeof item._原始 === 'object' ? item._原始 : {};
    for (const value of [item?.顯示名稱,item?.名稱,item?.名称,item?.name,original.顯示名稱,original.名稱,original.名称,original.name]) {
      const name = usefulItemName(value);
      if (name) return name;
    }
    const templateId = normalizeText(item?.模板ID || original.模板ID);
    if (STARTER_ITEM_NAMES[templateId]) return STARTER_ITEM_NAMES[templateId];
    const description = usefulItemName(item?.描述 || original.描述);
    if (/^starter-armor-/.test(templateId) && /[：:]/.test(description)) return description.split(/[：:]/).at(-1).trim();
