  };

  const normalizeItem = (raw, quantityOverride = null) => {
    const item = clone(raw || {});
    item.模板ID = normalizeText(item.模板ID || 'item-unknown') || 'item-unknown';
    item.模板版本 = Math.max(1, integer(item.模板版本, 1));
    item.顯示名稱 = inferredItemName(item);
    item.類別 = normalizeText(item.類別 || item.类别 || '特殊');
    item.子類 = normalizeText(item.子類 || item.子类 || '未分類');
    const isRecipe = /^recipe-/i.test(item.模板ID) || /配方(?:卷[轴軸])?/.test(`${item.顯示名稱}|${item.子類}`);
    if (isRecipe) {
