      item.子類 = '配方卷轴';
    }
    item.品質 = normalizeText(item.品質 || item.品质 || '普通');
    item.堆疊版本 = Math.max(1, integer(item.堆疊版本 ?? item.堆叠版本, 1));
    item.綁定狀態 = String(item.綁定狀態 || item.绑定状态 || '未綁定');
    item.鑑定狀態 = String(item.鑑定狀態 || item.鉴定状态 || '已鑑定');
    const inherentlyUnique = ['武器', '防具', '任務物品'].includes(item.類別) || item.品質 === '唯一' || item.鑑定狀態 === '未鑑定';
    item.基礎資料 = item.基礎資料 && typeof item.基礎資料 === 'object' ? item.基礎資料 : item.基础资料 && typeof item.基础资料 === 'object' ? item.基础资料 : {};
    const machine = item.基礎資料.機器效果 && typeof item.基礎資料.機器效果 === 'object'
      ? item.基礎資料.機器效果
      : item.基礎資料.机器效果 && typeof item.基礎資料.机器效果 === 'object'
