    machine.解除異常 = Array.isArray(machine.解除異常) ? machine.解除異常 : Array.isArray(machine.解除异常) ? machine.解除异常 : [];
    machine.添加異常 = machine.添加異常 && typeof machine.添加異常 === 'object' ? machine.添加異常 : machine.添加异常 && typeof machine.添加异常 === 'object' ? machine.添加异常 : {};
    machine.說明 = String(machine.說明 || machine.说明 || '');
    item.基礎資料.機器效果 = machine;
    const recipeCandidate = item.基礎資料.配方資料 ?? item.基礎資料.配方数据 ?? item.配方資料 ?? null;
    const recipeMeaningful = recipeCandidate && typeof recipeCandidate === 'object' && !Array.isArray(recipeCandidate)
      && Object.keys(recipeCandidate).length > 0
      && !['','recipe-unknown'].includes(normalizeText(recipeCandidate.ID));
    item.基礎資料.配方資料 = isRecipe && recipeMeaningful ? recipeCandidate : null;
    delete item.基礎資料.机器效果;
    delete item.基礎資料.配方数据;
    delete item.配方資料;
    item.可堆疊 = (item.可堆疊 ?? item.可堆叠) !== false && !inherentlyUnique && integer(item?.基礎資料?.耐久上限 ?? item?.基礎資料?.耐久上限值, 0) <= 0;
    item.數量 = Math.max(0, integer(quantityOverride ?? item.數量 ?? item.数量, 1));
    item.強化 = item.強化 && typeof item.強化 === 'object' ? item.強化 : item.强化 && typeof item.强化 === 'object' ? item.强化 : { S:0,Q:0,A:0,H:0,D:0,上限:0,記錄:[] };
    for (const key of ['S','Q','A','H','D','上限']) item.強化[key] = Math.max(0, integer(item.強化[key], 0));
    item.強化.記錄 = Array.isArray(item.強化.記錄) ? item.強化.記錄 : [];
    item.耐久 = Math.max(0, integer(item.耐久, integer(item.基礎資料.耐久上限, 0)));
    item.效果 = Array.isArray(item.效果) ? item.效果 : [];
    item.來源 = String(item.來源 || item.来源 || '');
    item.描述 = String(item.描述 || '');
    item.可交易 = item.可交易 !== false;
    item.可丟棄 = (item.可丟棄 ?? item.可丢弃) !== false;
    item.狀態 = String(item.狀態 || item.状态 || '完好');
    if (item.可堆疊) {
      item.實例ID = null;
      item.物品ID = `stack-${hashText(stackKey(item))}`;
    } else {
      item.實例ID = String(item.實例ID || item.物品ID || uniqueId('item'));
