  function stackKey(item) {
    return [
      String(item?.模板ID || ''),
      String(item?.品質 || '普通'),
      String(item?.綁定狀態 || '未綁定'),
      String(item?.鑑定狀態 || '已鑑定'),
      String(item?.堆疊版本 || 1)
