    ['bleed', /出血|流血|裂傷|裂伤/],
    ['burn', /燃燒|燃烧|灼燒|灼烧|著火/],
    ['freeze', /冰凍|冰冻|凍結|冻结/],
    ['fear', /恐慌|恐懼|恐惧|畏懼|畏惧/],
    ['silence', /沉默|封技|禁言/],
    ['curse', /詛咒|诅咒|咒蝕|咒蚀/],
    ['bind', /束縛|束缚|拘束|纏繞|缠绕/]
  ]);
  const STATUS_ICON_TOKENS = new Set(STATUS_ICON_RULES.map(([token]) => token));
  const isStatusPlaceholder = value => {
    const text = normalizeText(value).toLowerCase();
    return !text || ['status-unknown','未命名狀態','未命名状态','unknown status'].includes(text);
  };
  const canonicalStatusName = value => {
    const text = normalizeText(value);
    return STATUS_NAME_ALIASES[text] || text;
  };
  const statusIconToken = (name, supplied = '') => {
    const suppliedToken = normalizeText(supplied).toLowerCase();
    if (STATUS_ICON_TOKENS.has(suppliedToken)) return suppliedToken;
    const semanticText = `${canonicalStatusName(name)} ${normalizeText(supplied)}`;
    return STATUS_ICON_RULES.find(([,pattern]) => pattern.test(semanticText))?.[0] || 'warning';
  };
  const STATUS_STRENGTH_LABELS = Object.freeze({
    微弱:1, 輕微:1, 轻微:1, 弱:1,
    一般:2, 普通:2, 中等:2,
    強:3, 强:3, 強力:3, 强力:3,
    嚴重:4, 严重:4, 極強:4, 极强:4,
    致命:5, 災厄:5, 灾厄:5
  });
  const normalizeStatusStrength = value => {
    const numeric = Number(value);
    if (Number.isFinite(numeric)) return clamp(Math.trunc(numeric), 1, 5);
    const text = normalizeText(value);
    return STATUS_STRENGTH_LABELS[text] || 2;
  };
  const statusMachineRule = (name, strength) => {
    const level = normalizeStatusStrength(strength);
    const rules = {
      中毒:{ 類型:'週期HP', 間隔秒數:10, 每次HP變化:-level },
      出血:{ 類型:'週期HP', 間隔秒數:5, 每次HP變化:-level },
      燃燒:{ 類型:'週期HP', 間隔秒數:5, 每次HP變化:-(level * 2) },
      詛咒:{ 類型:'週期HP', 間隔秒數:30, 每次HP變化:-level },
      麻痺:{ 類型:'能力修正', 速度百分比:-(level * 15), 閃避率百分比:-(level * 10) },
      暈眩:{ 類型:'行動限制', 禁止行動:true, 速度百分比:-100, 閃避率百分比:-100, 準確率百分比:-100 },
      衰弱:{ 類型:'能力修正', STR百分比:-(level * 5), AGI百分比:-(level * 5) },
      睡眠:{ 類型:'行動限制', 禁止行動:true, 受擊解除:true, 速度百分比:-100, 閃避率百分比:-100, 防禦力百分比:-(level * 20) },
      黑暗:{ 類型:'能力修正', 準確率百分比:-(level * 12) },
      混亂:{ 類型:'能力修正', 準確率百分比:-(level * 10) },
      冰凍:{ 類型:'能力修正', 速度百分比:-(level * 20), 閃避率百分比:-(level * 15) },
      恐慌:{ 類型:'能力修正', 攻擊力百分比:-(level * 5), 準確率百分比:-(level * 5) },
      沉默:{ 類型:'行動限制', 禁止呼叫:true, 禁止特定技能:true, 速度百分比:-(level * 5), 準確率百分比:-(level * 5) },
      束縛:{ 類型:'能力修正', 速度百分比:-(level * 25), 閃避率百分比:-(level * 20) }
    };
    return clone(rules[canonicalStatusName(name)] || { 類型:'記錄' });
  };

  const normalizeStatusEffect = (raw, fallbackId = '') => {
    const source = raw && typeof raw === 'object' && !Array.isArray(raw) ? clone(raw) : {};
    const fallback = canonicalStatusName(fallbackId);
    const sourceName = isStatusPlaceholder(source.名稱) ? '' : canonicalStatusName(source.名稱);
    const sourceId = isStatusPlaceholder(source.ID || source.狀態ID) ? '' : normalizeText(source.ID || source.狀態ID);
    const name = sourceName || fallback || canonicalStatusName(sourceId) || '未命名狀態';
    const id = sourceId || fallback || name || 'status-unknown';
    const effectValue = source.效果;
    const effectText = normalizeText(source.效果說明 || (typeof effectValue === 'string' ? effectValue : ''));
    const description = normalizeText(source.描述 || source.說明 || effectText);
    const seconds = Math.max(0, integer(source.剩餘秒數 ?? source.剩餘時間 ?? source.剩余时间,
      Math.max(0, integer(source.剩餘分鐘 ?? source.剩余分钟, 0)) * 60));
    const finiteDuration = typeof source.有限持續時間 === 'boolean' ? source.有限持續時間 : seconds > 0;
    const strengthLevel = normalizeStatusStrength(source.強度等級 ?? source.強度 ?? source.强度 ?? source.類型);
    const strengthLabel = normalizeText(source.強度 || source.强度 || source.類型 || '') || String(strengthLevel);
    return {
      ID:id, 名稱:name, 類型:normalizeText(source.類型 || source.类型 || '異常') || '異常',
      強度:strengthLabel, 強度等級:strengthLevel,
      開始時間:normalizeText(source.開始時間 || source.开始时间 || ''),
      剩餘秒數:seconds, 剩餘分鐘:Math.ceil(seconds / 60), 有限持續時間:finiteDuration,
      結算累積秒數:Math.max(0, integer(source.結算累積秒數 ?? source.结算累积秒数, 0)),
      解除條件:normalizeText(source.解除條件 || source.解除条件 || ''),
      描述:description, 效果說明:effectText || description,
      圖示:statusIconToken(name, source.圖示 || source.图示),
      層數:Math.max(0, integer(source.層數 ?? source.层数, 1)),
      效果:Array.isArray(effectValue) ? effectValue : (typeof effectValue === 'string' ? effectValue : []),
      機器規則:statusMachineRule(name, strengthLevel),
      來源:normalizeText(source.來源 || source.来源 || '')
    };
  };

  const passiveFingerprint = raw => hashText(stableStringify({
    ID: raw.ID,
    名稱: raw.名稱,
    類型: raw.類型,
    描述: raw.描述,
    解鎖條件: raw.解鎖條件 || [],
    生效條件: raw.生效條件 || [],
    觸發時機: raw.觸發時機 || [],
    效果: raw.效果 || [],
    關聯劍技ID: raw.關聯劍技ID || []
  }));

  const normalizePassive = (raw, strict = false) => {
    const passive = clone(raw || {});
    if (strict && passive.自動生效 !== true) throw new Error('被動與特性必須在條件成立後自動生效');
    if (strict && passive.可主動使用 !== false) throw new Error('需要玩家主動發動的效果不能登記為被動或特性');
    passive.ID = normalizeText(passive.ID || 'passive-unknown') || 'passive-unknown';
    passive.名稱 = normalizeText(passive.名稱 || '未命名被動') || '未命名被動';
    passive.類型 = ['被動','特性'].includes(passive.類型) ? passive.類型 : '被動';
    passive.描述 = normalizeText(passive.描述 || '');
    passive.狀態 = ['未解鎖','已解鎖','停用'].includes(passive.狀態) ? passive.狀態 : '已解鎖';
    passive.自動生效 = true;
    passive.可主動使用 = false;
    passive.解鎖條件 = Array.isArray(passive.解鎖條件) ? passive.解鎖條件 : [];
    passive.生效條件 = Array.isArray(passive.生效條件) ? passive.生效條件 : [];
    passive.觸發時機 = Array.isArray(passive.觸發時機) ? [...new Set(passive.觸發時機.map(normalizeText).filter(Boolean))] : [];
    passive.效果 = Array.isArray(passive.效果) ? passive.效果 : [];
    passive.關聯劍技ID = Array.isArray(passive.關聯劍技ID) ? [...new Set(passive.關聯劍技ID.map(normalizeText).filter(Boolean))] : [];
    passive.定義版本 = Math.max(1, integer(passive.定義版本, 1));
    passive.定義指紋 = passiveFingerprint(passive);
    return passive;
  };

  const passiveConditionMet = (state, actorId, condition) => {
    const actor = baseActor(state, actorId);
    const type = String(condition?.類型 || '始終');
    const target = String(condition?.目標 || '');
    const value = finite(condition?.比較值, 0);
    if (type === '始終') return true;
    if (type === 'HP比例不高於') return actor.HP && finite(actor.HP.當前) / Math.max(1, finite(actor.HP.最大, 1)) * 100 <= value;
    if (type === 'HP比例不低於') return actor.HP && finite(actor.HP.當前) / Math.max(1, finite(actor.HP.最大, 1)) * 100 >= value;
    if (type === '裝備類別') return Object.values(actor.裝備 || {}).some(item => item?.類別 === target);
    if (type === '裝備子類') return Object.values(actor.裝備 || {}).some(item => item?.子類 === target);
    if (type === '狀態存在') return Boolean(actor.狀態效果?.[target]);
    if (type === '技能熟練度不低於') return finite(actor.技能?.[target]?.熟練度, 0) >= value;
    if (type === '場景狀態') return String(state.世界?.場景狀態 || '') === target;
    if (type === '事件旗標') {
      const [eventId, ...flagPath] = target.split('.').filter(Boolean);
      let cursor = state.世界?.事件?.[eventId]?.旗標;
      for (const key of flagPath) cursor = cursor?.[key];
      return cursor === true || cursor === value || String(cursor) === String(condition?.說明 || '');
    }
    return false;
  };

  const passiveModifiers = (state, actorId) => {
    const actor = baseActor(state, actorId);
    const equipped = new Set(actor?.技能槽?.已裝備技能ID || Object.keys(actor?.技能 || {}));
    const additions = { STR:0, AGI:0, 攻擊力:0, 防禦力:0, 速度:0, 準確率:0, 閃避率:0 };
    const percentages = { STR:0, AGI:0, 攻擊力:0, 防禦力:0, 速度:0, 準確率:0, 閃避率:0 };
    for (const [skillId, skill] of Object.entries(actor?.技能 || {})) {
      if (!equipped.has(skillId)) continue;
      for (const raw of skill?.被動效果 || []) {
        const passive = normalizePassive(raw);
        if (passive.狀態 !== '已解鎖' || !passive.生效條件.every(condition => passiveConditionMet(state, actorId, condition))) continue;
        for (const effect of passive.效果) {
          if (!(effect.目標 in additions)) continue;
          if (effect.類型 === '屬性加算') additions[effect.目標] += finite(effect.數值);
          if (effect.類型 === '屬性乘算') percentages[effect.目標] += finite(effect.數值);
        }
      }
    }
    return { additions, percentages };
  };

  const statusModifiers = actor => {
    const percentages = { STR:0, AGI:0, 攻擊力:0, 防禦力:0, 速度:0, 準確率:0, 閃避率:0 };
    const restrictions = { 禁止行動:false, 受擊解除:false, 禁止呼叫:false, 禁止特定技能:false };
    for (const [statusId, rawStatus] of Object.entries(actor?.狀態效果 || {})) {
      const status = normalizeStatusEffect(rawStatus, statusId);
      const rule = status.機器規則 || {};
      percentages.STR += finite(rule.STR百分比, 0);
      percentages.AGI += finite(rule.AGI百分比, 0);
      percentages.攻擊力 += finite(rule.攻擊力百分比, 0);
      percentages.防禦力 += finite(rule.防禦力百分比, 0);
      percentages.速度 += finite(rule.速度百分比, 0);
      percentages.準確率 += finite(rule.準確率百分比, 0);
      percentages.閃避率 += finite(rule.閃避率百分比, 0);
      if (rule.類型 === '行動限制') {
        for (const key of Object.keys(restrictions)) if (rule[key] === true) restrictions[key] = true;
      }
    }
    return { percentages, restrictions };
  };

  const derivedStats = (state, actorId = 'player') => {
    const actor = baseActor(state, actorId);
    const attrs = actor.屬性 || { STR:0, AGI:0 };
    const equipment = actor.裝備 || {};
    let equipmentSTR = 0, equipmentAGI = 0, attackBase = 0, defenseBase = 0, speedMod = 0, accuracyMod = 0;
    for (const [slot, raw] of Object.entries(equipment)) {
      if (!raw) continue;
      const item = normalizeItem(raw);
      const base = item.基礎資料 || {};
      equipmentSTR += integer(base?.屬性加成?.STR, 0);
      equipmentAGI += integer(base?.屬性加成?.AGI, 0);
      if (slot === '主手') attackBase += finite(base.攻擊, 0) + finite(item.強化?.S, 0) * 2 + finite(item.強化?.H, 0) * 3;
      defenseBase += finite(base.防禦, 0) + finite(item.強化?.D, 0) * 2;
      speedMod += finite(item.強化?.Q, 0) * 2 - finite(item.強化?.H, 0) * 2;
      accuracyMod += finite(item.強化?.A, 0) * 2;
    }
    const passive = passiveModifiers(state, actorId);
    const status = statusModifiers(actor);
    const applyPassive = (target, value) => (value + passive.additions[target]) * Math.max(0, 1 + passive.percentages[target] / 100);
    const applyStatus = (target, value) => value * Math.max(0, 1 + status.percentages[target] / 100);
    const STR = applyStatus('STR', applyPassive('STR', finite(attrs.STR, 0) + equipmentSTR));
    const AGI = applyStatus('AGI', applyPassive('AGI', finite(attrs.AGI, 0) + equipmentAGI));
    const attack = applyStatus('攻擊力', applyPassive('攻擊力', attackBase + STR * 1.5));
    const defense = applyStatus('防禦力', applyPassive('防禦力', defenseBase + STR * 0.5));
    const speed = applyStatus('速度', applyPassive('速度', 100 + AGI * 2 + speedMod));
    const accuracy = applyStatus('準確率', applyPassive('準確率', 100 + AGI * 0.5 + accuracyMod));
    const evasion = applyStatus('閃避率', applyPassive('閃避率', AGI * 0.5));
    return {
      基礎STR: finite(attrs.STR, 0), 基礎AGI: finite(attrs.AGI, 0),
      裝備STR: equipmentSTR, 裝備AGI: equipmentAGI,
      有效STR: STR, 有效AGI: AGI,
      攻擊力: Math.max(0, Math.round(attack)),
      防禦力: Math.max(0, Math.round(defense)),
      速度: Math.max(1, Math.round(speed)),
      準確率: Math.max(1, Math.round(accuracy)),
      閃避率: Math.max(0, Math.round(evasion)),
      技能槽已使用: Array.isArray(actor?.技能槽?.已裝備技能ID) ? actor.技能槽.已裝備技能ID.length : 0,
      技能槽總數: integer(actor?.技能槽?.基礎數量, 0) + integer(actor?.技能槽?.額外數量, 0),
      狀態限制: clone(status.restrictions)
    };
  };

  const experienceNeed = level => Math.max(100, Math.round(100 * Math.pow(Math.max(1, level), 1.55)));
  const applyExperience = (actor, amount) => {
    if (!actor?.經驗 || !actor?.等級) return;
    actor.經驗.當前 = Math.max(0, integer(actor.經驗.當前) + Math.max(0, integer(amount)));
    actor.經驗.下一級 = Math.max(1, integer(actor.經驗.下一級, experienceNeed(actor.等級)));
    while (actor.等級 < 100 && actor.經驗.當前 >= actor.經驗.下一級) {
      actor.經驗.當前 -= actor.經驗.下一級;
      actor.等級 += 1;
      actor.經驗.下一級 = experienceNeed(actor.等級);
      if (actor.屬性?.可分配點數 !== undefined) actor.屬性.可分配點數 += 3;
      if (actor.HP) {
        actor.HP.最大 += 50 + actor.等級 * 10;
        actor.HP.當前 = actor.HP.最大;
      }
    }
  };

  const moveWorld = (state, content) => {
    const nextFloor = clamp(integer(content.樓層, state.世界.當前樓層 || 1), 1, 100);
    const oldFloor = clamp(integer(state.世界.當前樓層, 1), 1, 100);
    state.世界.樓層檔案 ||= {};
    if (nextFloor !== oldFloor) {
      state.世界.樓層檔案[String(oldFloor)] = clone(state.世界.當前樓層檔案 || {});
      state.世界.當前樓層檔案 = clone(state.世界.樓層檔案[String(nextFloor)] || {});
      delete state.世界.樓層檔案[String(nextFloor)];
      state.世界.當前樓層 = nextFloor;
      state.世界.已解鎖樓層 = [...new Set([...(state.世界.已解鎖樓層 || []), nextFloor])].sort((a,b)=>a-b);
    }
    if (content.區域) state.世界.當前區域 = String(content.區域);
    if (content.詳細地點) state.世界.詳細地點 = String(content.詳細地點);
    if (content.區域狀態) state.世界.區域狀態 = String(content.區域狀態);
    advanceTime(state, content.時間分鐘);
  };

  const relationStage = value => {
    const v = clamp(integer(value), -100, 100);
    if (v <= -76) return '死敵';
    if (v <= -51) return '仇視';
    if (v <= -26) return '排斥';
    if (v <= -11) return '疏離';
    if (v <= 10) return '陌生';
    if (v <= 25) return '熟悉';
    if (v <= 50) return '信任';
    if (v <= 75) return '親近';
    return '深度羈絆';
  };

  const statusActors = state => {
    const rows = [['player', state.玩家]];
    for (const [id, character] of Object.entries(state.角色 || {})) rows.push([id, character?.戰鬥 || character]);
    return rows.filter(([,actor]) => actor && typeof actor === 'object');
  };
  const settleTimedStatuses = (state, elapsedSeconds) => {
    const elapsed = Math.max(0, integer(elapsedSeconds));
    if (!elapsed) return [];
    const summaries = [];
    for (const [actorId, actor] of statusActors(state)) {
      actor.狀態效果 = actor.狀態效果 && typeof actor.狀態效果 === 'object' ? actor.狀態效果 : {};
      for (const [key, rawStatus] of Object.entries(actor.狀態效果)) {
        const status = normalizeStatusEffect(rawStatus, key);
        const activeSeconds = status.有限持續時間 ? Math.min(elapsed, status.剩餘秒數) : elapsed;
        const rule = status.機器規則 || {};
        if (rule.類型 === '週期HP' && actor.HP && activeSeconds > 0) {
          const interval = Math.max(1, integer(rule.間隔秒數, 1));
          const total = Math.max(0, integer(status.結算累積秒數, 0)) + activeSeconds;
          const ticks = Math.floor(total / interval);
          status.結算累積秒數 = total % interval;
          if (ticks > 0) {
            const delta = integer(rule.每次HP變化, 0) * ticks;
            const before = integer(actor.HP.當前, 0);
            actor.HP.當前 = clamp(before + delta, 0, integer(actor.HP.最大, 1));
            summaries.push({ 角色ID:actorId, 狀態:status.名稱, 次數:ticks, HP變化:actor.HP.當前-before });
          }
        }
        if (status.有限持續時間) {
          status.剩餘秒數 = Math.max(0, status.剩餘秒數 - elapsed);
          status.剩餘分鐘 = Math.ceil(status.剩餘秒數 / 60);
          if (status.剩餘秒數 <= 0) { delete actor.狀態效果[key]; continue; }
        }
        actor.狀態效果[key] = status;
      }
    }
    return summaries;
  };

  const advanceTime = (state, minutes) => {
    const amount = Math.max(0, integer(minutes));
    if (!amount) return;
    settleTimedStatuses(state, amount * 60);
    const [year, month, day] = String(state.世界.日期 || '2022-11-06').split('-').map(Number);
    const [hour, minute] = String(state.世界.時間 || '13:25').split(':').map(Number);
    const date = new Date(Date.UTC(year || 2022, Math.max(0,(month || 1)-1), day || 6, hour || 0, minute || 0));
    date.setUTCMinutes(date.getUTCMinutes() + amount);
    state.世界.日期 = date.toISOString().slice(0,10);
    state.世界.時間 = date.toISOString().slice(11,16);
  };

  const actionLog = (state, action, status, summary, detail = {}) => {
    state.系統.行動日誌.push({
      ID: uniqueId('log'), 行動ID: action.ID, 類型: action.類型, 狀態: status,
      時間: nowText(state), 摘要: summary, 詳情: clone(detail)
    });
    state.系統.行動日誌 = state.系統.行動日誌.slice(-300);
  };

  const addNotification = (state, content, sender = 'system') => {
    const id = uniqueId('notification');
    state.通訊.通知[id] = { ID:id, 類型:'系統通知', 發送者ID:sender, 內容:String(content), 時間:nowText(state), 已讀:false };
  };

  const handleCharacterSync = (state, action) => {
    const c = action.內容 || {};
    const id = normalizeText(c.角色ID);
    if (!/^character-[a-z0-9][a-z0-9-]*$/i.test(id)) throw new Error(`角色同步需要固定character-* ID：${id || '空值'}`);
    let character = state.角色[id];
    if (!character) {
      if (!normalizeText(c.名稱)) throw new Error(`新角色${id}缺少名稱`);
      character = {
        ID:id, 名稱:c.名稱, 類型:c.角色類型 || 'NPC', 資料來源:c.資料來源 || '原創', 身份:c.身份 || '', 性別:c.性別 || '',
        外貌:c.外貌 || '', 最後已知位置:c.最後已知位置 || '', 近況:c.近況 || '', 當前目標:c.當前目標 || '',
        生活規律:c.生活規律 || '', 移動規律:c.移動規律 || '', 光標狀態:c.光標狀態 || '綠名', 公會ID:c.公會ID ?? null,
        對玩家關係:{ 好感:0, 階段:'陌生', 摘要:'初次确认接触', 標籤:[], 關鍵記憶:[], 邊界:[], 最後變化時間:'', 當日正向變化:0, 當日記錄日期:state.世界.日期 || '' },
        關聯任務ID:Array.isArray(c.關聯任務ID) ? [...new Set(c.關聯任務ID)] : [], 戰鬥:clone(c.戰鬥資料 ?? null), 交易:null, 服務:{},
        死亡:false, 死亡記錄:null, 最後更新時間:nowText(state)
      };
      state.角色[id] = character;
    }
    const fieldMap = {
      名稱:'名稱', 角色類型:'類型', 資料來源:'資料來源', 身份:'身份', 性別:'性別', 外貌:'外貌', 最後已知位置:'最後已知位置',
      近況:'近況', 當前目標:'當前目標', 生活規律:'生活規律', 移動規律:'移動規律', 光標狀態:'光標狀態', 公會ID:'公會ID', 關聯任務ID:'關聯任務ID'
    };
    for (const [sourceKey, targetKey] of Object.entries(fieldMap)) {
      if (Object.prototype.hasOwnProperty.call(c, sourceKey)) character[targetKey] = clone(c[sourceKey]);
    }
    character.ID = id;
    character.對玩家關係 ||= { 好感:0, 階段:'陌生', 摘要:'初次确认接触', 標籤:[], 關鍵記憶:[], 邊界:[], 最後變化時間:'', 當日正向變化:0, 當日記錄日期:state.世界.日期 || '' };
    if (Object.prototype.hasOwnProperty.call(c, '戰鬥資料')) character.戰鬥 = clone(c.戰鬥資料);
    if (Object.prototype.hasOwnProperty.call(c, '商店')) {
      if (c.商店 === null) character.交易 = null;
      else {
        const shop = c.商店 || {};
        character.交易 ||= { 類型:'NPC商店', Col:0, 庫存:{}, 定價策略:'固定價格', 價格表:{}, 是否無限庫存:false };
        character.交易.類型 = shop.類型 || character.交易.類型 || 'NPC商店';
        character.交易.Col = Math.max(0, integer(shop.Col, character.交易.Col));
        character.交易.定價策略 = shop.定價策略 || character.交易.定價策略 || '固定價格';
        character.交易.是否無限庫存 = shop.是否無限庫存 === true;
        character.交易.庫存 ||= {};
        character.交易.價格表 ||= {};
        for (const product of shop.商品 || []) {
          const templateId = normalizeText(product.模板ID);
          if (!templateId || templateId === 'item-unknown') throw new Error(`${character.名稱}的商品缺少固定模板ID`);
          const [oldKey] = findItem(character.交易.庫存, templateId);
          if (oldKey) delete character.交易.庫存[oldKey];
          const item = normalizeItem({
            物品ID:'', 模板ID:templateId, 模板版本:1, 實例ID:null, 顯示名稱:product.名稱,
            類別:product.類別, 子類:product.子類, 品質:product.品質, 堆疊版本:1, 可堆疊:true, 數量:product.數量,
            綁定狀態:'未綁定', 鑑定狀態:'已鑑定', 耐久:0, 強化:{S:0,Q:0,A:0,H:0,D:0,上限:0,記錄:[]},
            狀態:'完好', 效果:[], 來源:`${character.名稱}的商店`, 描述:product.描述, 可交易:true, 可丟棄:true,
            基礎資料:{ 槽位:'', 雙手武器:false, 攻擊:0, 防禦:0, 速度:100, 準確率:100, 耐久上限:0,
              需求等級:1, 需求屬性:{STR:0,AGI:0}, 屬性加成:{STR:0,AGI:0}, 機器效果:clone(product.機器效果 || {}), 材料標籤:[], 配方資料:clone(product.配方資料 || null) }
          }, product.數量);
          if (item.數量 > 0) addItem(character.交易.庫存, item, item.數量);
          const price = { 買入:Math.max(0, integer(product.買入價)), 賣出:Math.max(0, integer(product.賣出價)) };
          for (const key of ['買入下限','買入上限','賣出下限','賣出上限']) if (product[key] !== undefined) price[key] = Math.max(0, integer(product[key]));
          character.交易.價格表[templateId] = price;
        }
      }
    }
    if (c.在場 === true && !state.世界.當前場景角色ID.includes(id)) state.世界.當前場景角色ID.push(id);
    if (c.在場 === false) state.世界.當前場景角色ID = state.世界.當前場景角色ID.filter(value => value !== id);
    character.最後更新時間 = nowText(state);
    return `${c.操作 === '建立' ? '建立' : '更新'}角色${character.名稱}`;
  };

  const handleTaskSync = (state, action) => {
    const c = action.內容 || {};
    const id = normalizeText(c.任務ID);
    if (!/^task-[a-z0-9][a-z0-9-]*$/i.test(id)) throw new Error(`任务同步需要固定task-* ID：${id || '空值'}`);
    let task = state.任務[id];
    if (!task) {
      if (!normalizeText(c.名稱) || !normalizeText(c.類型) || !normalizeText(c.發起者ID)) throw new Error(`新任务${id}缺少名称、类型或发起者ID`);
      task = {
        ID:id, 類型:c.類型, 名稱:c.名稱, 狀態:c.狀態 || '候選', 發起者ID:c.發起者ID,
        參與者ID:Array.isArray(c.參與者ID) ? c.參與者ID : [], 樓層:integer(c.樓層, state.世界.當前樓層 || 1),
        地點:c.地點 || state.世界.詳細地點 || '', 階段:c.階段 || '', 描述:c.描述 || '', 目標:clone(c.目標 || []),
        線索:clone(c.線索 || []), 條件:clone(c.條件 || []), 關鍵物品模板ID:clone(c.關鍵物品模板ID || []),
        失敗條件:clone(c.失敗條件 || []), 獎勵預覽:clone(c.獎勵預覽 || {}), 分支:clone(c.分支 || {}), 結果:clone(c.結果 || {}),
        建立時間:nowText(state), 最後更新時間:nowText(state)
      };
      state.任務[id] = task;
    }
    const fields = ['類型','名稱','狀態','發起者ID','參與者ID','樓層','地點','階段','描述','目標','線索','條件','關鍵物品模板ID','失敗條件','獎勵預覽','分支','結果'];
    for (const field of fields) if (Object.prototype.hasOwnProperty.call(c, field)) task[field] = clone(c[field]);
    const npcOnly = new Set(['系統任務','支線任務','討伐任務','護送任務','調查任務','技能任務','生產任務','戰爭任務','交付任務']);
    if (npcOnly.has(task.類型) && state.角色?.[task.發起者ID]?.類型 !== 'NPC') throw new Error(`${task.名稱}必须由已建档NPC发出`);
    task.ID = id;
    task.參與者ID = [...new Set((task.參與者ID || []).map(value => ['user','{{user}}',state.玩家.名稱].includes(value) ? 'player' : value))];
    task.最後更新時間 = nowText(state);
    for (const roleId of [task.發起者ID, ...task.參與者ID]) {
      const role = state.角色?.[roleId];
      if (!role) continue;
      role.關聯任務ID = [...new Set([...(role.關聯任務ID || []), id])];
    }
    return `${c.操作 === '建立' ? '建立' : '更新'}任务${task.名稱}`;
  };

  const handleCommunication = (state, action) => {
    const c = action.內容 || {};
    const id = normalizeText(c.通訊ID);
    if (!id) throw new Error('通讯缺少固定ID');
    const message = { ID:id, 類型:c.類型, 發送者ID:c.發送者ID || 'system', 發送者名稱:c.發送者名稱 || '', 內容:c.內容 || '', 時間:c.時間 || nowText(state), 已讀:c.已讀 === true };
    if (c.類型 === '系統通知') state.通訊.通知[id] = message;
    else state.通訊.消息[id] = message;
    return `记录${c.類型}${id}`;
  };

  const tradePrice = (trade, line, source) => {
    const table = trade?.價格表 || {};
    const keys = [line.物品ID, line.模板ID, source?.物品ID, source?.模板ID].filter(Boolean);
    const entry = keys.map(key => table[key]).find(value => value && typeof value === 'object');
    if (!entry) return null;
    const field = line.方向 === '買入' ? '買入' : '賣出';
    const base = Math.max(0, integer(entry[field], 0));
    if (trade.定價策略 !== '允許議價') return { base, minimum:base, maximum:base };
    const minimum = Math.max(0, integer(entry[`${field}下限`], base));
    const maximum = Math.max(minimum, integer(entry[`${field}上限`], base));
    return { base, minimum, maximum };
  };

  const normalizeTradeSnapshot = raw => {
    const source = raw && typeof raw === 'object' && !Array.isArray(raw) ? clone(raw) : {};
    source.類型 = normalizeText(source.類型 || 'NPC商店') || 'NPC商店';
    source.Col = Math.max(0, integer(source.Col, 0));
    source.定價策略 = normalizeText(source.定價策略 || '固定價格') || '固定價格';
    source.是否無限庫存 = source.是否無限庫存 === true;
    source.庫存 = source.庫存 && typeof source.庫存 === 'object' && !Array.isArray(source.庫存) ? source.庫存 : {};
    source.價格表 = source.價格表 && typeof source.價格表 === 'object' && !Array.isArray(source.價格表) ? source.價格表 : {};
    const normalizedInventory = {};
    for (const [key, value] of Object.entries(source.庫存)) {
      const normalized = normalizeItem(value);
      const inventoryKey = normalized.物品ID || normalized.實例ID || normalized.模板ID || key;
      normalizedInventory[inventoryKey] = normalized;
    }
    source.庫存 = normalizedInventory;
    return source;
  };

  const inlineTradeSnapshot = content => {
    const inventory = {}, prices = {};
    for (const line of Array.isArray(content?.明細) ? content.明細 : []) {
      if (line?.方向 !== '買入' || !line?.物品快照) continue;
      const normalized = normalizeItem(line.物品快照, Math.max(1, integer(line.數量, 1)));
      normalized.數量 = Math.max(integer(normalized.數量, 1), Math.max(1, integer(line.數量, 1)));
      const key = normalized.物品ID || normalized.實例ID || normalized.模板ID || uniqueId('stock');
      inventory[key] = normalized;
      const ref = normalized.模板ID || key;
      const buy = Math.max(0, integer(line.單價, 0));
      prices[ref] = { 買入:buy, 賣出:Math.max(0, Math.floor(buy * 0.4)) };
    }
    if (!Object.keys(inventory).length) return null;
    return { 類型:'NPC商店', Col:0, 定價策略:'固定價格', 是否無限庫存:false, 庫存:inventory, 價格表:prices };
  };

  const ensureTradePartner = (state, content) => {
    const partnerId = canonicalCharacterId(content?.交易對象ID);
    if (!partnerId || partnerId === 'player') throw new Error('交易對象ID無效');
    content.交易對象ID = partnerId;
    const snapshot = content?.交易對象資料 && typeof content.交易對象資料 === 'object' && !Array.isArray(content.交易對象資料)
      ? clone(content.交易對象資料) : null;
    const inlineTrade = inlineTradeSnapshot(content);
    let partner = state.角色?.[partnerId];
    if (!partner) {
      const name = normalizeText(snapshot?.名稱 || content?.交易對象名稱 || '店主');
      const tradeData = snapshot?.交易 || inlineTrade;
      if (!tradeData) throw new Error(`首次交易缺少商店資料或物品快照：${name}`);
      partner = {
        ID:partnerId, 名稱:name, 類型:snapshot?.角色類型 || snapshot?.類型 || 'NPC', 資料來源:snapshot?.資料來源 || '原創',
        身份:snapshot?.身份 || '商人', 性別:snapshot?.性別 || '', 外貌:snapshot?.外貌 || '',
        最後已知位置:snapshot?.最後已知位置 || state.世界.詳細地點 || '', 近況:snapshot?.近況 || '正在與玩家交易。',
        當前目標:snapshot?.當前目標 || '', 生活規律:snapshot?.生活規律 || '', 移動規律:snapshot?.移動規律 || '',
        光標狀態:snapshot?.光標狀態 || '綠名', 公會ID:snapshot?.公會ID ?? null,
        對玩家關係:{ 好感:0, 階段:'陌生', 摘要:'首次確認接觸', 標籤:[], 關鍵記憶:[], 邊界:[], 最後變化時間:'', 當日正向變化:0, 當日記錄日期:state.世界.日期 || '' },
        關聯任務ID:Array.isArray(snapshot?.關聯任務ID) ? [...new Set(snapshot.關聯任務ID)] : [],
        戰鬥:clone(snapshot?.戰鬥資料 ?? snapshot?.戰鬥 ?? null), 交易:normalizeTradeSnapshot(tradeData),
        服務:clone(snapshot?.服務 || {}), 死亡:false, 死亡記錄:null, 最後更新時間:nowText(state)
      };
      state.角色[partnerId] = partner;
    } else {
      if (!partner.交易 && (snapshot?.交易 || inlineTrade)) partner.交易 = normalizeTradeSnapshot(snapshot?.交易 || inlineTrade);
      if (normalizeText(snapshot?.名稱 || content?.交易對象名稱)) partner.名稱 = normalizeText(snapshot?.名稱 || content?.交易對象名稱);
      partner.最後更新時間 = nowText(state);
    }
    partner.交易 = normalizeTradeSnapshot(partner.交易);
    for (const line of Array.isArray(content?.明細) ? content.明細 : []) {
      if (line?.方向 !== '買入' || !line?.物品快照) continue;
      const existing = findTradeItem(partner.交易.庫存, line)[1];
      if (existing) continue;
      const normalized = normalizeItem(line.物品快照, Math.max(1, integer(line.數量, 1)));
      normalized.數量 = Math.max(integer(normalized.數量, 1), Math.max(1, integer(line.數量, 1)));
      const key = normalized.物品ID || normalized.實例ID || normalized.模板ID || uniqueId('stock');
      partner.交易.庫存[key] = normalized;
      const ref = normalized.模板ID || key;
      partner.交易.價格表[ref] ||= { 買入:Math.max(0, integer(line.單價, 0)), 賣出:Math.max(0, Math.floor(integer(line.單價, 0) * 0.4)) };
    }
    if (!state.世界.當前場景角色ID.includes(partnerId)) state.世界.當前場景角色ID.push(partnerId);
    if (!partner.交易) throw new Error(`交易對象沒有交易資料：${partner.名稱}`);
    return partner;
  };

  const GENERIC_MERCHANT_PATTERN = /(?:NPC|老闆|老板|店主|店員|店员|商店|商販|商贩|攤位|摊位|烘焙|麵包店|面包店|旅店|旅館|旅馆|客棧|客栈|餐館|餐馆|酒館|酒馆|藥店|药店|武器店|防具店|雜貨店|杂货店)/i;
  const isGenericMerchant = content => {
    const name = normalizeText(content?.交易對象名稱 || content?.服務提供者名稱 || content?.對象名稱 || '');
    const id = normalizeText(content?.交易對象ID || content?.服務提供者ID || '');
    return GENERIC_MERCHANT_PATTERN.test(`${name} ${id}`);
  };

  const generalConsumptionFromTrade = content => {
    const lines = Array.isArray(content?.明細) ? content.明細 : [];
    const acquired = [];
    const lost = [];
    let lineBuy = 0, lineSell = 0;
    for (const line of lines) {
      const qty = Math.max(1, integer(line?.數量, 1));
      const unit = Math.max(0, integer(line?.單價, 0));
      if (line?.方向 === '買入') {
        if (!line?.物品快照) throw new Error(`一般消費缺少物品快照：${line?.模板ID || line?.物品ID || '未知物品'}`);
        acquired.push({ 物品:clone(line.物品快照), 數量:qty });
        lineBuy += unit * qty;
      } else {
        lost.push({ 物品ID:normalizeText(line?.物品ID || line?.模板ID), 數量:qty });
        lineSell += unit * qty;
      }
    }
    const explicitPay = Math.abs(integer(content?.玩家支付Col, 0));
    const explicitGain = Math.abs(integer(content?.對方支付Col, 0));
    return {
      對象名稱:normalizeText(content?.交易對象名稱 || '普通商店'),
      項目名稱:normalizeText(content?.說明 || '普通購買'),
      玩家支付Col:explicitPay || lineBuy,
      玩家取得Col:explicitGain || lineSell,
      取得物品:acquired,
      失去物品:lost,
      時間分鐘:Math.max(0, integer(content?.時間分鐘, 0)),
      場景狀態:'',
      說明:normalizeText(content?.說明 || '')
    };
  };

  const handleGeneralConsumption = (state, action) => {
    const c = action.內容 || {};
    const pay = Math.max(0, Math.abs(integer(c.玩家支付Col, 0)));
    const gain = Math.max(0, Math.abs(integer(c.玩家取得Col, 0)));
    if (state.玩家.Col < pay) throw new Error(`Col不足：需要${pay}，目前${state.玩家.Col}`);
    const inventory = state.玩家.背包;
    const removals = [];
    for (const row of c.失去物品 || []) {
      const ref = normalizeText(row?.物品ID || row?.模板ID);
      const qty = Math.max(1, integer(row?.數量, 1));
      const [, found] = findItem(inventory, ref);
      if (!found || integer(found.數量, 0) < qty) throw new Error(`一般消費缺少交付物品：${ref || '未知物品'}`);
      removals.push({ ref, qty });
    }
    const acquisitions = (c.取得物品 || []).map(row => {
      if (!row?.物品) throw new Error('一般消費取得物品缺少完整物品快照');
      return { item:normalizeItem(row.物品), qty:Math.max(1, integer(row.數量, 1)) };
    });
    state.玩家.Col = Math.max(0, state.玩家.Col - pay + gain);
    for (const row of removals) removeItem(inventory, row.ref, row.qty);
    for (const row of acquisitions) addItem(inventory, row.item, row.qty);
    if (normalizeText(c.場景狀態)) state.世界.場景狀態 = normalizeText(c.場景狀態);
    advanceTime(state, Math.max(0, integer(c.時間分鐘, 0)));
    return `${normalizeText(c.對象名稱 || '普通商店')}：${normalizeText(c.項目名稱 || c.說明 || '一般消費')}，淨支出${pay - gain} Col`;
  };

  const handleTrade = (state, action) => {
    if (isGenericMerchant(action.內容) && !state.角色?.[canonicalCharacterId(action.內容?.交易對象ID)]) {
      return handleGeneralConsumption(state, { ...action, 類型:'一般消費', 內容:generalConsumptionFromTrade(action.內容) });
    }
    const content = action.內容;
    const partnerId = content.交易對象ID;
    const partner = ensureTradePartner(state, content);
    const lines = Array.isArray(content.明細) ? content.明細 : [];
    const aggregateBuy = Math.max(0, integer(content.玩家支付Col, 0));
    const aggregateSell = Math.max(0, integer(content.對方支付Col, 0));
    const hasPricedBuyLine = lines.some(line => line.方向 === '買入' && Math.max(0, integer(line.單價, 0)) > 0);
    const hasPricedSellLine = lines.some(line => line.方向 === '賣出' && Math.max(0, integer(line.單價, 0)) > 0);
    if (aggregateBuy > 0 && hasPricedBuyLine) throw new Error('買入交易同時填入明細單價與整包總價，會造成重複計價');
    if (aggregateSell > 0 && hasPricedSellLine) throw new Error('賣出交易同時填入明細單價與整包總價，會造成重複計價');
    let totalBuy = aggregateBuy;
    let totalSell = aggregateSell;
    if (!lines.length && totalBuy <= 0 && totalSell <= 0) throw new Error('交易內容為空');
    const transfers = [];
    let bundleBuyMinimum = 0, bundleBuyMaximum = 0, bundleSellMinimum = 0, bundleSellMaximum = 0;
    let hasBuyPriceReference = false, hasSellPriceReference = false;
    for (const line of lines) {
      const qty = Math.max(1, integer(line.數量, 1));
      const unitPrice = Math.max(0, integer(line.單價, 0));
      if (line.方向 === '買入') {
        const inventory = partner.交易.庫存;
        let [, source] = findTradeItem(inventory, line);
        if (!source) throw new Error(`商店沒有物品：${line.物品ID || line.模板ID}`);
        if (!partner.交易.是否無限庫存 && integer(source.數量, 0) < qty) throw new Error(`${source.顯示名稱}庫存不足`);
        const price = tradePrice(partner.交易, line, source);
        if (partner.交易.類型 !== '玩家交易' && !price) throw new Error(`${source.顯示名稱}尚未建立價格`);
        if (aggregateBuy > 0 && price?.maximum > 0) {
          hasBuyPriceReference = true;
          bundleBuyMinimum += price.minimum * qty;
          bundleBuyMaximum += price.maximum * qty;
        } else if (price && (unitPrice < price.minimum || unitPrice > price.maximum)) {
          throw new Error(`${source.顯示名稱}單價${unitPrice}不在有效報價${price.minimum}至${price.maximum}之內`);
        }
        if (aggregateBuy === 0) totalBuy += unitPrice * qty;
        transfers.push({ direction:'buy', source:clone(source), quantity:qty, reference:source.物品ID, infinite:partner.交易.是否無限庫存 });
      } else {
        const [, source] = findTradeItem(state.玩家.背包, line);
        if (!source) throw new Error(`玩家沒有物品：${line.物品ID || line.模板ID}`);
        if (source.可交易 === false) throw new Error(`${source.顯示名稱}不可交易`);
        if (integer(source.數量, 0) < qty) throw new Error(`${source.顯示名稱}數量不足`);
        const price = tradePrice(partner.交易, line, source);
        if (partner.交易.類型 !== '玩家交易' && !price) throw new Error(`${source.顯示名稱}沒有店主收購價`);
        if (aggregateSell > 0 && price?.maximum > 0) {
          hasSellPriceReference = true;
          bundleSellMinimum += price.minimum * qty;
          bundleSellMaximum += price.maximum * qty;
        } else if (price && (unitPrice < price.minimum || unitPrice > price.maximum)) {
          throw new Error(`${source.顯示名稱}收購單價${unitPrice}不在有效報價${price.minimum}至${price.maximum}之內`);
        }
        if (aggregateSell === 0) totalSell += unitPrice * qty;
        transfers.push({ direction:'sell', source:clone(source), quantity:qty, reference:source.物品ID });
      }
    }
    if (aggregateBuy > 0 && hasBuyPriceReference && (aggregateBuy < bundleBuyMinimum || aggregateBuy > bundleBuyMaximum)) {
      throw new Error(`買入整包總價${aggregateBuy}不在有效報價${bundleBuyMinimum}至${bundleBuyMaximum}之內`);
    }
    if (aggregateSell > 0 && hasSellPriceReference && (aggregateSell < bundleSellMinimum || aggregateSell > bundleSellMaximum)) {
      throw new Error(`賣出整包總價${aggregateSell}不在有效報價${bundleSellMinimum}至${bundleSellMaximum}之內`);
    }
    const net = totalBuy - totalSell;
    if (net > state.玩家.Col) throw new Error(`Col不足：需要${net}，目前${state.玩家.Col}`);
    if (net < 0 && partner.交易.Col < -net) throw new Error(`交易對象Col不足`);
    state.玩家.Col -= net;
    partner.交易.Col += net;
    for (const transfer of transfers) {
      if (transfer.direction === 'buy') {
        const moved = transfer.infinite ? normalizeItem(transfer.source, transfer.quantity) : removeItem(partner.交易.庫存, transfer.reference, transfer.quantity);
        addItem(state.玩家.背包, moved, transfer.quantity);
      } else {
        const moved = removeItem(state.玩家.背包, transfer.reference, transfer.quantity);
        addItem(partner.交易.庫存, moved, transfer.quantity);
      }
    }
    advanceTime(state, content.時間分鐘);
    return `與${partner.名稱}完成交易，淨支出${net} Col`;
  };

  const handleItemGrant = (state, action) => {
    const {目標ID, 物品, 數量, 時間分鐘} = action.內容;
    const inventory = inventoryFor(state, 目標ID);
    addItem(inventory, 物品, 數量);
    advanceTime(state, 時間分鐘);
    return `${目標ID === 'player' ? '玩家' : state.角色[目標ID]?.名稱 || 目標ID}取得${數量}個${物品.顯示名稱}`;
  };

  const applyItemUse = (state, content, { advance = true } = {}) => {
    const {使用者ID, 物品ID, 數量, 目標ID} = content;
    const inventory = inventoryFor(state, 使用者ID);
    const [, found] = findItem(inventory, 物品ID);
    if (!found) throw new Error(`找不到使用物品：${物品ID}`);
    const item = normalizeItem(found);
    const qty = Math.max(1, integer(數量, 1));
    if (!['消耗品','食物','工具'].includes(item.類別)) throw new Error(`${item.顯示名稱}不能直接使用`);

    const recipe = item.基礎資料?.配方資料;
    if (/配方/.test(item.子類) || recipe) {
      if (使用者ID !== 'player') throw new Error('配方卷軸目前只允許玩家學習');
      if (!recipe || typeof recipe !== 'object') throw new Error(`${item.顯示名稱}缺少配方資料`);
      const recipeId = normalizeText(recipe.ID || item.模板ID);
      if (!recipeId || recipeId === 'recipe-unknown') throw new Error(`${item.顯示名稱}缺少固定配方ID`);
      state.玩家.已知配方 ||= {};
      if (state.玩家.已知配方[recipeId]) throw new Error(`已學會配方：${recipe.名稱 || item.顯示名稱}`);
      state.玩家.已知配方[recipeId] = clone({ ...recipe, ID:recipeId });
      const skill = Object.values(state.玩家.技能 || {}).find(value => [value?.名稱,value?.子類].includes(recipe.技能));
      if (skill) {
        skill.配方ID = [...new Set([...(skill.配方ID || []), recipeId])];
      }
      removeItem(inventory, 物品ID, 1);
      return `使用${item.顯示名稱}並學會配方「${recipe.名稱 || recipeId}」`;
    }

    const target = baseActor(state, 目標ID);
    const effect = item.基礎資料?.機器效果 || {};
    const hpDelta = integer(effect.HP) * qty;
    if (hpDelta > 0 && !(item.類別 === '消耗品' && /藥水|药水|potion/i.test(`${item.子類}|${item.模板ID}`))) {
      throw new Error('HP恢復只允許來自藥水');
    }
    removeItem(inventory, 物品ID, qty);
    if (target.HP) target.HP.當前 = clamp(integer(target.HP.當前) + hpDelta, 0, integer(target.HP.最大, 1));
    if (目標ID === 'player') state.玩家.Col = Math.max(0, state.玩家.Col + integer(effect.Col) * qty);
    target.狀態效果 ||= {};
    for (const statusId of effect.解除異常 || []) {
      for (const [key, value] of Object.entries(target.狀態效果)) {
        if ([key,value?.ID,value?.名稱].includes(statusId)) delete target.狀態效果[key];
      }
    }
    for (const [statusId, status] of Object.entries(effect.添加異常 || {})) target.狀態效果[statusId] = normalizeStatusEffect(status, statusId);
    if (advance) advanceTime(state, integer(effect.時間分鐘) * qty);
    return `使用${qty}個${item.顯示名稱}`;
  };

  const handleItemUse = (state, action) => applyItemUse(state, action.內容, { advance:true });

  const meetsRequirements = (state, actorId, item) => {
    const actor = baseActor(state, actorId);
    const base = item.基礎資料 || {};
    const stats = derivedStats(state, actorId);
    const level = integer(actor.等級, 1);
    return level >= integer(base.需求等級, 1) && stats.有效STR >= integer(base?.需求屬性?.STR, 0) && stats.有效AGI >= integer(base?.需求屬性?.AGI, 0);
  };


  const handleItemDiscard = (state, action) => {
    const c = action.內容;
    const inventory = inventoryFor(state, c.角色ID);
    const [, item] = findItem(inventory, c.物品ID);
    if (!item) throw new Error(`找不到丟棄物品：${c.物品ID}`);
    if (item.可丟棄 === false) throw new Error(`${item.顯示名稱}不可丟棄`);
    removeItem(inventory, c.物品ID, c.數量);
    return `丟棄${c.數量}個${item.顯示名稱}`;
  };

  const SKILL_STAGES = Object.freeze([
    { 名稱:'初學', 最低:0 },
    { 名稱:'熟練', 最低:100 },
    { 名稱:'精通', 最低:300 },
    { 名稱:'大師', 最低:700 },
    { 名稱:'宗師', 最低:1500 }
  ]);

  const makeStarterSwordSkill = (branchId, index, name, options = {}) => ({
    ID:`sword-skill-${branchId}-${index + 1}`, 名稱:name, 類型:'劍技',
    技能描述:options.描述 || `${name}是${options.武器 || '武器'}分支的固定劍技。`,
    觸發條件:[], 威力倍率:finite(options.威力倍率, 1 + index * 0.15), 固定傷害:integer(options.固定傷害, 0),
    AGI倍率:finite(options.AGI倍率, 0.1 + index * 0.04), 命中修正:integer(options.命中修正, 0),
    前搖:finite(options.前搖, Math.max(0.15, 0.38 - index * 0.03)), 後搖:finite(options.後搖, 0.45 + index * 0.05),
    冷卻:'無', 特殊效果:Array.isArray(options.特殊效果) ? options.特殊效果 : [], 資源消耗:{}, 成功時資源變化:{}, 被動聯動ID:[]
  });
  const STARTER_SKILL_BRANCHES = Object.freeze({
    sword:{ 名稱:'單手直劍', 武器:'單手直劍', 劍技:['斜斬','垂直斬','平面斬','音速衝擊','水平方陣斬'] },
    rapier:{ 名稱:'細劍', 武器:'細劍', 劍技:['線性攻擊','傾斜突刺','平行刺擊','流星','三角刺擊'] },
    scimitar:{ 名稱:'曲刀', 武器:'曲刀', 劍技:['圓弧斬','幻月','漩流','旋車','龍捲風'] },
    dagger:{ 名稱:'短劍', 武器:'短劍', 劍技:['快捷刺擊','銳爪','葉形線','飛劍','三重鐮刀'] },
    mace:{ 名稱:'戰錘', 武器:'戰錘', 劍技:['重擊','麻痺衝擊','麻痺轟爆','震地擊','破城連擊'] },
    axe:{ 名稱:'戰斧', 武器:'戰斧', 劍技:['斬裂','剝伐','掠奪者','斷頭斬','暴風斬'] },
    spear:{ 名稱:'長槍', 武器:'長槍', 劍技:['直線突擊','穿刺','連環突刺','彗星突擊','破陣槍'] },
    greatsword:{ 名稱:'雙手劍', 武器:'雙手劍', 劍技:['垂直重斬','水平重斬','雪崩斬','旋風重斬','終結斬'] },
    katana2h:{ 名稱:'雙手太刀', 武器:'雙手太刀', 劍技:['袈裟斬','浮舟','逆輪','緋扇','絕空'] }
  });
  const starterCombatSkill = (weaponId, proficiency = 0) => {
    const branchId = normalizeText(weaponId).toLowerCase();
    const branch = STARTER_SKILL_BRANCHES[branchId];
    if (!branch) return null;
    const thresholds = [0, 100, 300, 700, 1500];
    const unlockTable = branch.劍技.map((name, index) => ({
      熟練度:thresholds[index],
      劍技:makeStarterSwordSkill(branchId, index, name, { 武器:branch.武器, 命中修正:index === 0 ? 5 : 0 })
    }));
    return syncSkillProgression({
      ID:`skill-combat-${branchId}`, 名稱:branch.名稱, 類別:'戰鬥', 子類:branch.武器,
      熟練度:Math.max(0, integer(proficiency, 0)), 階段:'初學', 階段序號:0, 階段內熟練度:0, 下階段需求:100,
      劍技解鎖表:unlockTable, 描述:`${branch.武器}的系統技能。熟練度跨越固定門檻時由核心自動解鎖劍技。`,
      已解鎖能力:[], 已解鎖劍技:[], 被動效果:[], 配方ID:[], 公開:true
    });
  };

  const syncSkillProgression = skill => {
    if (!skill || typeof skill !== 'object') return skill;
    skill.熟練度 = Math.max(0, integer(skill.熟練度, 0));
    let index = 0;
    for (let i = 0; i < SKILL_STAGES.length; i += 1) if (skill.熟練度 >= SKILL_STAGES[i].最低) index = i;
    const current = SKILL_STAGES[index];
    const next = SKILL_STAGES[index + 1] || null;
    skill.階段 = current.名稱;
    skill.階段序號 = index;
    skill.階段內熟練度 = skill.熟練度 - current.最低;
    skill.下階段需求 = next ? next.最低 - current.最低 : 0;
    skill.劍技解鎖表 = Array.isArray(skill.劍技解鎖表) ? skill.劍技解鎖表 : [];
    skill.已解鎖劍技 = Array.isArray(skill.已解鎖劍技) ? skill.已解鎖劍技 : [];
    const unlocked = new Set(skill.已解鎖劍技.map(value => normalizeText(value?.ID || value)).filter(Boolean));
    for (const row of [...skill.劍技解鎖表].sort((a,b) => integer(a?.熟練度) - integer(b?.熟練度))) {
      const swordSkill = row?.劍技;
      const swordSkillId = normalizeText(swordSkill?.ID);
      if (!swordSkillId || skill.熟練度 < integer(row?.熟練度) || unlocked.has(swordSkillId)) continue;
      skill.已解鎖劍技.push(clone(swordSkill));
      unlocked.add(swordSkillId);
    }
    return skill;
  };

  const handleSkill = (state, action) => {
    const c = action.內容;
    const actor = baseActor(state, c.角色ID);
    if (!actor.技能?.[c.技能ID]) throw new Error(`找不到技能：${c.技能ID}`);
    actor.技能槽 ||= { 基礎數量:2, 額外數量:0, 已裝備技能ID:[] };
    actor.技能槽.已裝備技能ID = Array.isArray(actor.技能槽.已裝備技能ID) ? actor.技能槽.已裝備技能ID : [];
    if (c.操作 === '卸下') {
      actor.技能槽.已裝備技能ID = actor.技能槽.已裝備技能ID.filter(id => id !== c.技能ID);
      return `卸下技能${actor.技能[c.技能ID].名稱}`;
    }
    const limit = integer(actor.技能槽.基礎數量,0) + integer(actor.技能槽.額外數量,0);
    if (actor.技能槽.已裝備技能ID.includes(c.技能ID)) return `技能${actor.技能[c.技能ID].名稱}已裝備`;
    if (actor.技能槽.已裝備技能ID.length >= limit) throw new Error('技能槽已滿');
    actor.技能槽.已裝備技能ID.push(c.技能ID);
    return `裝備技能${actor.技能[c.技能ID].名稱}`;
  };

  const handleSkillData = (state, action) => {
    const c = action.內容;
    const actor = baseActor(state, c.角色ID);
    actor.技能 ||= {};
    if (c.操作 === '習得技能') {
      if (!c.技能) throw new Error('習得技能缺少完整技能資料');
      const skillId = normalizeText(c.技能ID || c.技能.ID);
      if (!skillId || skillId === 'skill-unknown') throw new Error('技能必須使用固定技能ID');
      if (actor.技能[skillId]) throw new Error(`技能已存在：${skillId}`);
      const skill = clone(c.技能);
      skill.ID = skillId;
      skill.已解鎖能力 = Array.isArray(skill.已解鎖能力) ? skill.已解鎖能力 : [];
      skill.已解鎖劍技 = Array.isArray(skill.已解鎖劍技) ? skill.已解鎖劍技 : [];
      skill.被動效果 = (skill.被動效果 || []).map(value => normalizePassive(value, true));
      actor.技能[skillId] = syncSkillProgression(skill);
      return `習得技能${skill.名稱}`;
    }
    const skill = actor.技能[c.技能ID];
    if (!skill) throw new Error(`找不到技能：${c.技能ID}`);
    if (c.操作 === '解鎖能力') {
      if (!c.能力?.ID) throw new Error('解鎖能力缺少固定能力ID');
      skill.已解鎖能力 ||= [];
      const existing = skill.已解鎖能力.find(value => value.ID === c.能力.ID);
      if (existing && stableStringify(existing) !== stableStringify(c.能力)) throw new Error(`能力定義已存在且內容不同：${c.能力.ID}`);
      if (!existing) skill.已解鎖能力.push(clone(c.能力));
      return `解鎖${skill.名稱}能力：${c.能力.名稱}`;
    }
    if (c.操作 === '解鎖劍技') {
      if (!c.劍技?.ID) throw new Error('解鎖劍技缺少固定劍技ID');
      skill.已解鎖劍技 ||= [];
      const existing = skill.已解鎖劍技.find(value => value.ID === c.劍技.ID);
      if (existing && stableStringify(existing) !== stableStringify(c.劍技)) throw new Error(`劍技定義已存在且內容不同：${c.劍技.ID}`);
      if (!existing) skill.已解鎖劍技.push(clone(c.劍技));
      return `解鎖${skill.名稱}劍技：${c.劍技.名稱}`;
    }
    if (!c.被動) throw new Error('解鎖被動缺少完整被動資料');
    const passive = normalizePassive(c.被動, true);
    if (!passive.ID || passive.ID === 'passive-unknown') throw new Error('被動與特性必須使用固定ID');
    skill.被動效果 ||= [];
    const index = skill.被動效果.findIndex(value => value.ID === passive.ID);
    if (index < 0) {
      passive.定義版本 = 1;
      passive.變更原因 = c.原因 || passive.變更原因 || '首次解鎖';
      passive.最後定義時間 = nowText(state);
      skill.被動效果.push(passive);
      return `解鎖${skill.名稱}被動：${passive.名稱}`;
    }
    const current = normalizePassive(skill.被動效果[index]);
    if (current.定義指紋 === passive.定義指紋) return `${passive.名稱}定義未變更`;
    if (!c.原因.trim() || !passive.前置事件ID || passive.定義版本 !== current.定義版本 + 1) {
      throw new Error(`${passive.名稱}已存在；修改定義需要原因、前置事件ID與連續版本號`);
    }
    passive.變更原因 = c.原因;
    passive.最後定義時間 = nowText(state);
    skill.被動效果[index] = passive;
    return `更新${skill.名稱}被動：${passive.名稱} V${passive.定義版本}`;
  };

  const handleEquipment = (state, action) => {
    const {角色ID, 操作, 物品ID, 槽位} = action.內容;
    const inventory = inventoryFor(state, 角色ID);
    const equipment = equipmentFor(state, 角色ID);
    if (操作 === '卸下') {
      const current = equipment[槽位];
      if (!current) throw new Error(`${槽位}沒有裝備`);
      addItem(inventory, current, 1);
      equipment[槽位] = null;
      if (槽位 === '主手' && current?.基礎資料?.雙手武器) equipment.副手 = null;
      return `卸下${current.顯示名稱}`;
    }
    const [, raw] = findItem(inventory, 物品ID);
    if (!raw) throw new Error(`背包中找不到裝備：${物品ID}`);
    const item = normalizeItem(raw);
    if (!['武器','防具'].includes(item.類別)) throw new Error(`${item.顯示名稱}不是裝備`);
    if (!meetsRequirements(state, 角色ID, item)) throw new Error(`${item.顯示名稱}未達裝備需求`);
    const actualSlot = String(item.基礎資料?.槽位 || 槽位);
    if (actualSlot && actualSlot !== 槽位) throw new Error(`${item.顯示名稱}只能裝備於${actualSlot}`);
    const moved = removeItem(inventory, 物品ID, 1);
    if (equipment[槽位]) addItem(inventory, equipment[槽位], 1);
    if (moved.基礎資料?.雙手武器) {
      if (槽位 !== '主手') throw new Error('雙手武器只能裝備於主手');
      if (equipment.副手) addItem(inventory, equipment.副手, 1);
      equipment.副手 = null;
    }
    equipment[槽位] = moved;
    return `裝備${moved.顯示名稱}`;
  };

  const consumeMaterials = (inventory, materials) => {
    const checks = materials.map(req => {
      const [, item] = findItem(inventory, req.物品ID || req.模板ID);
      if (!item || integer(item.數量, 0) < integer(req.數量, 1)) throw new Error(`材料不足：${req.物品ID || req.模板ID}`);
      return req;
    });
    for (const req of checks) removeItem(inventory, req.物品ID || req.模板ID, req.數量);
  };

  const handleLifeSkill = (state, action) => {
    const c = action.內容;
    if (c.角色ID !== 'player') throw new Error('NPC生活技能請使用NPC服務');
    const skill = Object.values(state.玩家.技能).find(x => x?.類別 === '生活' && x?.名稱 === c.技能);
    if (!skill) throw new Error(`尚未習得生活技能：${c.技能}`);
    const inventory = state.玩家.背包;
    if (['採集','釣魚'].includes(c.操作)) {
      if (!c.產出物品) throw new Error(`${c.操作}缺少產出物品`);
      addItem(inventory, c.產出物品, c.數量);
      skill.熟練度 += Math.max(1, c.數量);
      advanceTime(state, c.時間分鐘);
      return `${c.操作}取得${c.數量}個${c.產出物品.顯示名稱}`;
    }
    if (c.操作 === '修理') {
      const [, item] = findItem(inventory, c.目標物品ID);
      if (!item) throw new Error(`找不到修理目標：${c.目標物品ID}`);
      consumeMaterials(inventory, c.材料);
      item.耐久 = Math.max(item.耐久, integer(item?.基礎資料?.耐久上限, item.耐久));
      skill.熟練度 += 1;
      advanceTime(state, c.時間分鐘);
      return `修理${item.顯示名稱}`;
    }
    if (c.操作 === '鑑定') {
      const [, item] = findItem(inventory, c.目標物品ID);
      if (!item) throw new Error(`找不到鑑定目標：${c.目標物品ID}`);
      item.鑑定狀態 = '已鑑定';
      skill.熟練度 += 1;
      advanceTime(state, c.時間分鐘);
      return `鑑定${item.顯示名稱}`;
    }
    if (c.操作 === '強化') {
      const [, item] = findItem(inventory, c.目標物品ID);
      if (!item) throw new Error(`找不到強化目標：${c.目標物品ID}`);
      const total = ['S','Q','A','H','D'].reduce((sum,key)=>sum+integer(item.強化?.[key],0),0);
      const cap = integer(item.強化?.上限, 0);
      if (!c.強化方向 || total >= cap) throw new Error(`強化次數已達上限或方向無效`);
      consumeMaterials(inventory, c.材料);
      item.強化[c.強化方向] += 1;
      item.強化.記錄.push({ 方向:c.強化方向, 時間:nowText(state), 行動ID:action.ID });
      skill.熟練度 += 2;
      advanceTime(state, c.時間分鐘);
      return `強化${item.顯示名稱}（${c.強化方向}+1）`;
    }
    const recipe = state.玩家.已知配方?.[c.配方ID];
    if (!recipe) throw new Error(`找不到配方：${c.配方ID}`);
    const requirements = Array.isArray(recipe.材料需求) ? recipe.材料需求 : c.材料;
    consumeMaterials(inventory, requirements);
    const output = recipe.產出物品 || c.產出物品;
    if (!output) throw new Error(`配方沒有產出物品`);
    const roll = parseInt(hashText(action.ID), 36) % 100 + 1;
    const chance = clamp(60 + Math.floor(integer(skill.熟練度,0) / 10), 5, 95);
    advanceTime(state, c.時間分鐘);
    if (roll > chance) {
      skill.熟練度 += 1;
      return `${c.技能}製作失敗（${roll}/${chance}）`;
    }
    addItem(inventory, output, c.數量);
    skill.熟練度 += Math.max(2, c.數量 * 2);
    return `${c.技能}製作${c.數量}個${output.顯示名稱}`;
  };

  const ensureNpcServiceProvider = (state, content) => {
    const providerId = canonicalCharacterId(content?.服務提供者ID);
    if (!providerId || providerId === 'player') throw new Error('服務提供者ID無效');
    content.服務提供者ID = providerId;
    const inline = content?.服務資料 && typeof content.服務資料 === 'object' && !Array.isArray(content.服務資料) ? clone(content.服務資料) : null;
    const serviceId = normalizeText(content?.服務項目ID) || uniqueId('service');
    let provider = state.角色?.[providerId];
    if (!provider) {
      const inferredType = /旅店|住宿|房間|inn|hotel/i.test(`${serviceId} ${inline?.名稱 || ''} ${content?.說明 || ''}`) ? '旅店' : (inline?.類型 || '固定服務');
      const service = inline || { 名稱:normalizeText(content?.說明 || 'NPC服務'), 類型:inferredType, 價格:Math.max(0, integer(content?.玩家支付Col, 0)), 時間分鐘:inferredType === '旅店' ? 480 : Math.max(0, integer(content?.時間分鐘, 0)), 可用:true };
      service.名稱 ||= inferredType === '旅店' ? '住宿一晚' : 'NPC服務';
      service.類型 ||= inferredType;
      service.價格 = Math.max(0, integer(service.價格 ?? content?.玩家支付Col, 0));
      service.時間分鐘 = Math.max(0, integer(service.時間分鐘 ?? content?.時間分鐘, inferredType === '旅店' ? 480 : 0));
      service.可用 = service.可用 !== false;
      provider = {
        ID:providerId, 名稱:normalizeText(content?.服務提供者名稱 || '服務人員'), 類型:'NPC', 資料來源:'原創', 身份:inferredType === '旅店' ? '旅店店員' : '服務提供者', 性別:'', 外貌:'',
        最後已知位置:state.世界.詳細地點 || '', 近況:'正在為玩家提供服務。', 當前目標:'', 生活規律:'', 移動規律:'', 光標狀態:'綠名', 公會ID:null,
        對玩家關係:{ 好感:0, 階段:'陌生', 摘要:'首次確認接觸', 標籤:[], 關鍵記憶:[], 邊界:[], 最後變化時間:'', 當日正向變化:0, 當日記錄日期:state.世界.日期 || '' },
        關聯任務ID:[], 戰鬥:null, 交易:normalizeTradeSnapshot({類型:'NPC商店',Col:0,定價策略:'固定價格',是否無限庫存:true,庫存:{},價格表:{}}),
        服務:{ [serviceId]:service }, 死亡:false, 死亡記錄:null, 最後更新時間:nowText(state)
      };
      state.角色[providerId] = provider;
    } else {
      provider.服務 ||= {};
      if (!provider.服務[serviceId] && inline) provider.服務[serviceId] = clone(inline);
      if (normalizeText(content?.服務提供者名稱)) provider.名稱 = normalizeText(content.服務提供者名稱);
    }
    if (!state.世界.當前場景角色ID.includes(providerId)) state.世界.當前場景角色ID.push(providerId);
    return { provider, service:provider.服務?.[serviceId], serviceId };
  };

  const ordinaryServiceConsumption = content => {
    const service = content?.服務資料 && typeof content.服務資料 === 'object' ? content.服務資料 : {};
    const type = normalizeText(service.類型 || '');
    const count = Math.max(1, integer(content?.數量, 1));
    const pay = Math.max(0, Math.abs(integer(content?.玩家支付Col, 0)) || Math.max(0, integer(service.價格, 0)) * count);
    const minutes = Math.max(0, integer(content?.時間分鐘, 0) || Math.max(0, integer(service.時間分鐘, 0)) * count);
    return {
      對象名稱:normalizeText(content?.服務提供者名稱 || '普通服務場所'),
      項目名稱:normalizeText(service.名稱 || content?.說明 || '一般服務'),
      玩家支付Col:pay, 玩家取得Col:0, 取得物品:[], 失去物品:[],
      時間分鐘:minutes, 場景狀態:type === '旅店' ? '休息' : '', 說明:normalizeText(content?.說明 || '')
    };
  };

  const handleNpcService = (state, action) => {
    const c = action.內容;
    const inlineType = normalizeText(c?.服務資料?.類型 || '');
    const ordinaryType = ['旅店','住宿','餐飲','餐饮','普通服務','普通服务'].includes(inlineType);
    if (isGenericMerchant(c) && ordinaryType && !normalizeText(c?.目標物品ID)) {
      return handleGeneralConsumption(state, { ...action, 類型:'一般消費', 內容:ordinaryServiceConsumption(c) });
    }
    const { provider, service } = ensureNpcServiceProvider(state, c);
    if (!service || service.可用 === false) throw new Error(`服務不可用：${c.服務項目ID}`);
    const count = Math.max(1, integer(c.數量, 1));
    const price = Math.max(0, integer(c.玩家支付Col, 0) || integer(service.價格, 0) * count);
    if (state.玩家.Col < price) throw new Error(`Col不足：需要${price}`);
    const inventory = state.玩家.背包;
    const materials = (service.材料需求 || []).map(req => ({ 模板ID:req.模板ID, 數量:integer(req.數量,1)*count }));
    if (materials.length) consumeMaterials(inventory, materials);
    state.玩家.Col -= price;
    if (provider.交易) provider.交易.Col += price;
    const type = service.類型;
    if (type === '修理') {
      const [, item] = findItem(inventory, c.目標物品ID);
      if (!item) throw new Error('沒有指定可修理物品');
      item.耐久 = integer(item?.基礎資料?.耐久上限, item.耐久);
    } else if (['鑑定','鑑定委託'].includes(type)) {
      const [, item] = findItem(inventory, c.目標物品ID);
      if (!item) throw new Error('沒有指定可鑑定物品');
      item.鑑定狀態 = '已鑑定';
    } else if (type === '旅店') {
      state.世界.場景狀態 = '休息';
    } else if (type === '交通') {
      if (!service.目的地) throw new Error('交通服務缺少目的地');
      moveWorld(state, { ...service.目的地, 時間分鐘:0 });
    } else {
      if (!service.產出物品) throw new Error(`${type}缺少固定產出`);
      addItem(inventory, service.產出物品, integer(service.產出數量,1)*count);
    }
    advanceTime(state, integer(service.時間分鐘, 0) * count);
    return `${provider.名稱}完成${service.名稱}`;
  };

  const handleParty = (state, action) => {
    const c = action.內容;
    const party = state.玩家.隊伍;
    if (c.操作 === '加入') {
      if (!state.角色[c.角色ID]) throw new Error(`找不到角色：${c.角色ID}`);
      if (c.角色ID === 'player' || ['user','{{user}}',normalizeText(state.玩家.名稱)].includes(normalizeText(c.角色ID))) return '玩家已經在隊伍中';
      if (Object.keys(party.成員).length >= 6) throw new Error('隊伍人數已達六人上限');
      party.成員[c.角色ID] = { 類型:c.成員類型, 加入時間:nowText(state) };
      return `${state.角色[c.角色ID].名稱}加入隊伍`;
    }
    if (c.操作 === '離開' || c.操作 === '踢出') {
      if (c.角色ID === 'player') throw new Error('玩家不能從自己的隊伍資料中移除');
      if (!party.成員[c.角色ID]) throw new Error('角色不在隊伍中');
      delete party.成員[c.角色ID];
      if (party.隊長ID === c.角色ID) party.隊長ID = 'player';
      return `${state.角色[c.角色ID]?.名稱 || c.角色ID}離開隊伍`;
    }
    if (c.操作 === '更改隊長') {
      if (!party.成員[c.新隊長ID]) throw new Error('新隊長不在隊伍中');
      party.隊長ID = c.新隊長ID;
      return `隊長變更為${c.新隊長ID === 'player' ? state.玩家.名稱 : state.角色[c.新隊長ID]?.名稱}`;
    }
    party.戰利品規則 = c.戰利品規則 || party.戰利品規則;
    return `戰利品規則變更為${party.戰利品規則}`;
  };

  const handleRelation = (state, action) => {
    const c = action.內容;
    const character = state.角色?.[c.角色ID];
    if (!character) throw new Error(`找不到角色：${c.角色ID}`);
    const relation = character.對玩家關係;
    const today = String(state.世界.日期 || '');
    if (relation.當日記錄日期 !== today) {
      relation.當日記錄日期 = today;
      relation.當日正向變化 = 0;
    }
    const requested = integer(c.好感變化);
    const remainingPositive = Math.max(0, 10 - integer(relation.當日正向變化));
    const applied = requested > 0 ? Math.min(requested, remainingPositive) : requested;
    relation.好感 = clamp(integer(relation.好感) + applied, -100, 100);
    if (applied > 0) relation.當日正向變化 = Math.min(10, integer(relation.當日正向變化) + applied);
    relation.階段 = relationStage(relation.好感);
    if (c.摘要) relation.摘要 = c.摘要;
    if (c.記憶) {
      const memory = clone(c.記憶);
      memory.ID ||= uniqueId('memory');
      memory.時間 ||= nowText(state);
      relation.關鍵記憶.push(memory);
      relation.關鍵記憶 = relation.關鍵記憶.slice(-100);
    }
    relation.最後變化時間 = nowText(state);
    const capped = applied !== requested ? `（本日正向上限，原請求${requested >= 0 ? '+' : ''}${requested}）` : '';
    return `${character.名稱}好感${applied >= 0 ? '+' : ''}${applied}${capped}，階段為${relation.階段}`;
  };

  const handleMove = (state, action) => {
    moveWorld(state, action.內容);
    return `移動至第${state.世界.當前樓層}層 ${state.世界.當前區域} ${state.世界.詳細地點}`;
  };

  const handleAttribute = (state, action) => {
    const c = action.內容;
    const points = Math.max(1, integer(c.點數,1));
    if (state.玩家.屬性.可分配點數 < points) throw new Error('可分配屬性點不足');
    state.玩家.屬性[c.屬性] += points;
    state.玩家.屬性.可分配點數 -= points;
    return `${c.屬性}+${points}`;
  };

  const handleQuestReward = (state, action) => {
    const c = action.內容;
    const task = state.任務?.[c.任務ID];
    if (!task) throw new Error(`找不到任務：${c.任務ID}`);
    if (task.狀態 !== '已完成') throw new Error('任務尚未完成');
    applyExperience(state.玩家, c.經驗);
    state.玩家.Col += Math.max(0, integer(c.Col));
    for (const entry of c.物品 || []) addItem(state.玩家.背包, entry.物品, entry.數量);
    advanceTime(state, c.時間分鐘);
    return `領取任務「${task.名稱}」獎勵`;
  };

  const handleStatus = (state, action) => {
    const c = action.內容 || {};
    const actor = baseActor(state, c.角色ID || 'player');
    actor.狀態效果 ||= {};
    if (c.操作 === '清除') {
      actor.狀態效果 = {};
      return `清除${c.角色ID || 'player'}的全部狀態`;
    }
    if (c.操作 === '移除') {
      const reference = normalizeText(c.狀態ID || c.狀態名稱);
      if (!reference) throw new Error('移除狀態缺少狀態ID');
      let removed = false;
      for (const [key, value] of Object.entries(actor.狀態效果)) {
        if ([key,value?.ID,value?.名稱].map(normalizeText).includes(reference)) {
          delete actor.狀態效果[key];
          removed = true;
        }
      }
      if (!removed) throw new Error(`找不到狀態：${reference}`);
      return `移除狀態${reference}`;
    }
    const source = c.狀態效果;
    if (!source || typeof source !== 'object') throw new Error(`${c.操作}狀態缺少狀態效果`);
    const rows = c.狀態ID || c.狀態名稱 || source.ID || source.名稱
      ? [[normalizeText(c.狀態ID || c.狀態名稱 || source.ID || source.名稱), source]]
      : Object.entries(source);
    if (!rows.length) throw new Error(`${c.操作}狀態沒有可處理內容`);
    for (const [fallbackId, rawStatus] of rows) {
      const status = normalizeStatusEffect(rawStatus, fallbackId);
      const key = normalizeText(c.狀態ID || c.狀態名稱 || fallbackId || status.ID || status.名稱);
      if (c.操作 === '添加') status.開始時間 = nowText(state);
      actor.狀態效果[key] = status;
    }
    return `${c.操作}${rows.length}個狀態`;
  };

  const applyCombatSettlementEvent = (state, event) => {
    const type = normalizeText(event?.類型);
    const actorId = normalizeText(event?.角色ID || 'player') || 'player';
    if (type === 'HP變化') {
      const actor = baseActor(state, actorId);
      if (!actor.HP) throw new Error(`角色沒有HP資料：${actorId}`);
      const before = integer(actor.HP.當前, 0);
      actor.HP.當前 = clamp(before + integer(event?.數值, 0), 0, integer(actor.HP.最大, 1));
      return `${actorId} HP ${actor.HP.當前 - before >= 0 ? '+' : ''}${actor.HP.當前 - before}`;
    }
    if (type === '經驗') {
      const actor = baseActor(state, actorId);
      applyExperience(actor, Math.max(0, integer(event?.數值, 0)));
      return `${actorId} 經驗+${Math.max(0, integer(event?.數值, 0))}`;
    }
    if (type === 'Col') {
      const amount = integer(event?.數值, 0);
      if (actorId === 'player') state.玩家.Col = Math.max(0, integer(state.玩家.Col, 0) + amount);
      else {
        const actor = baseActor(state, actorId);
        actor.Col = Math.max(0, integer(actor.Col, 0) + amount);
      }
      return `${actorId} Col ${amount >= 0 ? '+' : ''}${amount}`;
    }
    if (type === '物品使用') {
      return applyItemUse(state, {
        使用者ID:normalizeText(event?.使用者ID || actorId || 'player'),
        物品ID:normalizeText(event?.物品ID),
        數量:Math.max(1, integer(event?.數量, 1)),
        目標ID:normalizeText(event?.目標ID || actorId || 'player')
      }, { advance:false });
    }
    if (type === '時間推進') {
      const minutes = Math.max(0, integer(event?.分鐘, 0));
      advanceTime(state, minutes);
      return `時間推進${minutes}分鐘`;
    }
    throw new Error(`不支援的戰鬥結算事件：${type || '空白'}`);
  };

  const handleCombat = (state, action) => {
    const c = action.內容;
    const events = Array.isArray(c.結算事件) ? [...c.結算事件].sort((a,b) => integer(a?.順序, 0) - integer(b?.順序, 0)) : [];
    const eventMode = events.length > 0;
    let eventMinutes = 0;
    for (const event of events) {
      applyCombatSettlementEvent(state, event);
      if (normalizeText(event?.類型) === '時間推進') eventMinutes += Math.max(0, integer(event?.分鐘, 0));
    }
    for (const change of c.變化) {
      const actor = baseActor(state, change.角色ID);
      if (!eventMode) {
        if (actor.HP) actor.HP.當前 = clamp(integer(actor.HP.當前) + integer(change.HP), 0, integer(actor.HP.最大,1));
        applyExperience(actor, change.經驗);
        if (change.角色ID === 'player') state.玩家.Col += Math.max(0, integer(change.Col));
        else if (state.角色[change.角色ID]?.交易) state.角色[change.角色ID].交易.Col += Math.max(0, integer(change.Col));
      }
      for (const [skillId, amount] of Object.entries(change.熟練度 || {})) {
        if (actor.技能?.[skillId]) {
          actor.技能[skillId].熟練度 += Math.max(0, integer(amount));
          syncSkillProgression(actor.技能[skillId]);
        }
      }
      const equipment = actor.裝備 || {};
      const inventory = change.角色ID === 'player' ? state.玩家.背包 : (actor.背包 || {});
      for (const [slotOrId, delta] of Object.entries(change.耐久 || {})) {
        const target = findEquippedItem(equipment, slotOrId) || findItem(inventory, slotOrId)[1];
        if (target) {
          target.耐久 = Math.max(0, integer(target.耐久) + integer(delta));
          if (target.耐久 <= 0) target.狀態 = '損壞';
        }
      }
      for (const itemEntry of change.物品 || []) addItem(inventory, itemEntry.物品, itemEntry.數量);
    }
    const remainingMinutes = Math.max(0, integer(c.時間分鐘, 0) - eventMinutes);
    if (remainingMinutes > 0) advanceTime(state, remainingMinutes);
    if (c.戰鬥結束) {
      state.世界.當前遭遇 = null;
      state.世界.場景狀態 = '日常';
    }
    return c.摘要 || `完成戰鬥結算：${c.戰鬥ID}`;
  };


  const handlers = {
    角色同步: handleCharacterSync,
    任務同步: handleTaskSync,
    通訊: handleCommunication,
    一般消費: handleGeneralConsumption,
    交易: handleTrade,
    物品取得: handleItemGrant,
    物品使用: handleItemUse,
    物品丟棄: handleItemDiscard,
    技能: handleSkill,
    技能資料: handleSkillData,
    裝備: handleEquipment,
    生活技能: handleLifeSkill,
    NPC服務: handleNpcService,
    隊伍: handleParty,
    關係: handleRelation,
    狀態: handleStatus,
    時間: (state, action) => { advanceTime(state, action.內容.分鐘); return `時間推進${action.內容.分鐘}分鐘`; },
    移動: handleMove,
    屬性: handleAttribute,
    任務獎勵: handleQuestReward,
    戰鬥: handleCombat
  };

  const normalizeInventory = inventory => {
    if (!inventory || typeof inventory !== 'object' || Array.isArray(inventory)) return {};
    const items = Object.values(inventory).map(clone);
    for (const key of Object.keys(inventory)) delete inventory[key];
    for (const raw of items) {
      const item = normalizeItem(raw);
      if (item.數量 > 0) addItem(inventory, item, item.數量);
    }
    return inventory;
  };

  const normalizeSkills = actor => {
    actor.技能 ||= {};
    for (const [skillId, skill] of Object.entries(actor.技能)) {
      if (!skill || typeof skill !== 'object') { delete actor.技能[skillId]; continue; }
      skill.ID = skillId;
      skill.被動效果 = (Array.isArray(skill.被動效果) ? skill.被動效果 : []).map(value => normalizePassive(value));
      skill.已解鎖能力 = Array.isArray(skill.已解鎖能力) ? skill.已解鎖能力 : [];
      skill.已解鎖劍技 = Array.isArray(skill.已解鎖劍技) ? skill.已解鎖劍技 : [];
