globalThis.__SAOP_V5_HUD_NAVIGATION__ = (state, action, id = '', detailOpen = false) => {
  const next = { ...state };
  let nextDetailOpen = detailOpen;
  if (action === 'menu') {
    next.menu = !next.menu;
    if (!next.menu) { next.primary = null; next.sub = null; nextDetailOpen = false; }
  } else if (action === 'primary') {
    next.menu = true;
    if (next.primary === id) next.primary = null;
    else next.primary = id;
    next.sub = null;
    nextDetailOpen = false;
  } else if (action === 'sub') {
    if (next.sub === id && detailOpen) { next.sub = null; nextDetailOpen = false; }
    else { next.sub = id; nextDetailOpen = true; }
  } else if (action === 'close-detail') {
    next.sub = null;
    nextDetailOpen = false;
  }
  return { state: next, detailOpen: nextDetailOpen };
};

globalThis.__SAO_V48_FIT_SCALE__ = (naturalWidth, availableWidth, preferred = 1) => {
  const natural = Math.max(1, Number(naturalWidth) || 1);
  const available = Math.max(1, Number(availableWidth) || 1);
  const wanted = Math.min(1.3, Math.max(.55, Number(preferred) || 1));
  return Math.min(wanted, Math.max(.55, available / natural));
};

globalThis.__SAO_V48_DETAIL_TRANSITION__ = (trail, layer) => {
  const list = Array.isArray(trail) ? trail : [];
  const depth = Math.max(1, Math.trunc(Number(layer?.depth) || 1));
  const identity = value => [value?.type || '', value?.key || '', value?.group || '', value?.name || '', value?.sub || ''].join('|');
  const base = list.slice(0, depth - 1);
  const current = list[depth - 1];
  if (current && identity(current) === identity(layer)) return base;
  return [...base, { ...layer, depth, id: `layer-${Date.now()}-${Math.random().toString(36).slice(2, 6)}` }];
};

globalThis.__SAO_V423_SCOPE_CSS__ = (source, rootId) => {
  const scope = `#${rootId}`;
  const findBlockEnd = (text, openIndex) => {
    let depth = 1;
    let quote = '';
    for (let index = openIndex + 1; index < text.length; index += 1) {
      const char = text[index];
      if (quote) {
        if (char === '\\') index += 1;
        else if (char === quote) quote = '';
        continue;
      }
      if (char === '"' || char === "'") { quote = char; continue; }
      if (char === '{') depth += 1;
      if (char === '}' && --depth === 0) return index;
    }
    return text.length - 1;
  };
  const scopeBlock = text => {
    let output = '';
    let cursor = 0;
    while (cursor < text.length) {
      const open = text.indexOf('{', cursor);
      if (open < 0) { output += text.slice(cursor); break; }
      const preludeStart = Math.max(text.lastIndexOf('}', open - 1), cursor - 1) + 1;
      output += text.slice(cursor, preludeStart);
      const prelude = text.slice(preludeStart, open);
      const close = findBlockEnd(text, open);
      const body = text.slice(open + 1, close);
      const trimmed = prelude.trim();
      if (trimmed.startsWith('@media') || trimmed.startsWith('@supports') || trimmed.startsWith('@container') || trimmed.startsWith('@layer')) {
        output += `${prelude}{${scopeBlock(body)}}`;
      } else if (trimmed.startsWith('@')) {
        output += `${prelude}{${body}}`;
      } else {
        const leading = prelude.slice(0, prelude.indexOf(trimmed));
        const selectors = trimmed.split(',').map(raw => {
          const selector = raw.trim();
          return selector.includes(scope) ? selector : `${scope} ${selector}`;
        }).join(',');
        output += `${leading}${selectors}{${body}}`;
      }
      cursor = close + 1;
    }
    return output;
  };
  return scopeBlock(String(source || ''));
};

globalThis.__SAOP_V5_IS_DUEL_LOG__ = log => {
  if (log?.類型 !== '戰鬥') return false;
  const content = log?.詳情?.內容 || log?.詳情 || {};
  const battleType = String(content?.戰鬥類型 || '').trim();
  if (battleType === '決鬥' || battleType === 'PvP') return true;
